// =====================================
// Fungsi bantuan
// =====================================

function dapatkanCalon(id) {
  return DATA_CALON.find(c => c.id === id);
}

function senaraiCalonMengikutParti(parti) {
  return DATA_CALON.filter(c => c.parti === parti);
}

function senaraiCalonMengikutNegeri(negeri) {
  return DATA_CALON.filter(c => c.negeri === negeri);
}

function jumlahCalon() {
  return DATA_CALON.length;
}